function validate([s, t]) {
  if (s.length < 1 || s.length > 1000) return 's needs 1 to 1000 letters.';
  if (t.length < 1 || t.length > 1000) return 't needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase English letters.';
  return null;
}

