function longestPalindrome(s, t) {
  const palindromeStarts = (text) => {
    const longest = new Array(text.length + 1).fill(0);
    for (let center = 0; center < 2 * text.length - 1; center++) {
      let left = center >> 1;
      let right = left + (center & 1);
      while (left >= 0 && right < text.length && text[left] === text[right]) {
        longest[left] = Math.max(longest[left], right - left + 1);
        left--;
        right++;
      }
    }
    return longest;
  };
  const reversed = [...t].reverse().join('');
  const fromS = palindromeStarts(s);
  const fromR = palindromeStarts(reversed);
  let best = 0;
  let below = new Array(reversed.length + 1).fill(0);
  for (let i = s.length; i >= 0; i--) {
    const row = new Array(reversed.length + 1).fill(0);
    for (let j = 0; j <= reversed.length; j++) {
      row[j] = Math.max(fromS[i], fromR[j]);
      if (i < s.length && j < reversed.length && s[i] === reversed[j]) {
        row[j] = Math.max(row[j], 2 + below[j + 1]);
      }
      best = Math.max(best, row[j]);
    }
    below = row;
  }
  return best;
}

