function longestPalindrome(s, t) {
  const pieces = (text) => {
    const list = [''];
    for (let a = 0; a < text.length; a++) {
      for (let b = a + 1; b <= text.length; b++) list.push(text.slice(a, b));
    }
    return list;
  };
  let best = 0;
  for (const left of pieces(s)) {
    for (const right of pieces(t)) {
      const joined = left + right;
      if (joined.length > best && joined === [...joined].reverse().join('')) best = joined.length;
    }
  }
  return best;
}

