function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, pick(1, size === 'large' ? 4 : 3));
  const word = (length) => Array.from({ length }, () => alphabet[pick(0, alphabet.length - 1)]).join('');
  const mirror = (text) => [...text].reverse().join('');
  if (size !== 'large') return [word(pick(1, 7)), word(pick(1, 7))];
  const mode = pick(0, 2);
  if (mode === 0) return [word(1000), word(1000)];
  if (mode === 1) {
    // Plant some text plus a palindrome in one string and the text's mirror image in the other, inside random filler.
    const outer = word(pick(100, 300));
    const half = word(pick(0, 50));
    const palindrome = half + (rand() < 0.5 ? alphabet[0] : '') + mirror(half);
    const inS = rand() < 0.5;
    const pad = (core) => {
      const before = word(pick(0, 1000 - core.length));
      return before + core + word(1000 - before.length - core.length);
    };
    return [pad(outer + (inS ? palindrome : '')), pad((inS ? '' : palindrome) + mirror(outer))];
  }
  // Nearly uniform strings: a few b's scattered among a's.
  const sprinkle = () => Array.from({ length: 1000 }, () => (rand() < 0.003 ? 'b' : 'a')).join('');
  return [sprinkle(), sprinkle()];
}
